use xiom.io;

enum Suit {
  Hearts,
  Diamonds,
  Clubs,
  Spades,
}

enum Rank {
  Ace,
  Two,
  Three,
  Four,
  Five,
  Six,
  Seven,
  Eight,
  Nine,
  Ten,
  Jack,
  Queen,
  King,
}

type Card = {
  suit: Suit;
  rank: Rank;
}

fn suit_name(s: Suit) -> Str {
  match s {
    Hearts => { return "Hearts"; }
    Diamonds => { return "Diamonds"; }
    Clubs => { return "Clubs"; }
    Spades => { return "Spades"; }
  }
}

fn rank_name(r: Rank) -> Str {
  match r {
    Ace => { return "Ace"; }
    Two => { return "Two"; }
    Three => { return "Three"; }
    Four => { return "Four"; }
    Five => { return "Five"; }
    Six => { return "Six"; }
    Seven => { return "Seven"; }
    Eight => { return "Eight"; }
    Nine => { return "Nine"; }
    Ten => { return "Ten"; }
    Jack => { return "Jack"; }
    Queen => { return "Queen"; }
    King => { return "King"; }
  }
}

fn Card.describe(self) -> Str {
  return rank_name(rank) + " of " + suit_name(suit);
}

fn is_pair(a: Card, b: Card) -> Bool {
  return a.rank == b.rank;
}

fn main() -> Int {
  let ace_spades = Card{ suit: Suit.Spades; rank: Rank.Ace; };
  let ace_hearts = Card{ suit: Suit.Hearts; rank: Rank.Ace; };
  if is_pair(ace_spades, ace_hearts) { return 1; }
  return 0;
}
